package plan
import("os";"path/filepath";"testing";"github.com/stretchr/testify/require")
func TestLoomOfficialMarkerUnknown(t *testing.T){
 data,err:=os.ReadFile(filepath.Join(os.Getenv("MO_LOOM_PROBE_DIR"),"query-marker96.wire"));require.NoError(t,err);var got Query;require.NoError(t,got.Unmarshal(data));require.Len(t,got.Nodes,2);require.Empty(t,got.Nodes[0].DedupKeyExprs,"unknown scalar96 must not become diagnostic95");require.Equal(t,int32(7),got.Nodes[1].DedupKeyExprs[0].GetCol().ColPos);t.Log("actual official219 protobuf: unknown96 ignored, released95 diagnostic preserved")
}

