package plan
import("os";"path/filepath";"testing";"github.com/stretchr/testify/require")
func TestLoomCurrentMarkerExport(t *testing.T){
 q:=&Query{Nodes:[]*Node{{NodeType:Node_WINDOW,ScalarSetReaggregation:true},{NodeType:Node_JOIN,DedupKeyExprs:[]*Expr{{Typ:Type{Id:23},Expr:&Expr_Col{Col:&ColRef{RelPos:1,ColPos:7}}}}}},Steps:[]int32{0}}
 data,err:=q.Marshal();require.NoError(t,err);require.NoError(t,os.WriteFile(filepath.Join(os.Getenv("MO_LOOM_PROBE_DIR"),"query-marker96.wire"),data,0600));var got Query;require.NoError(t,got.Unmarshal(data));require.True(t,got.Nodes[0].ScalarSetReaggregation);require.Equal(t,int32(7),got.Nodes[1].DedupKeyExprs[0].GetCol().ColPos)
 t.Logf("candidate marker96+diagnostic95 bytes=%d",len(data))
}
